using System.Text.Json.Serialization;

namespace PS2Home.Core;

/// <summary>
/// Aggregated hardware capability report generated by the native diagnostics helper.
/// </summary>
public record NativeDiagnosticsResult
{
    [JsonIgnore]
    public bool IsAvailable { get; init; } = true;

    [JsonPropertyName("schema_version")]
    public int SchemaVersion { get; init; } = 1;

    [JsonPropertyName("cpu")]
    public NativeCpuInfo? Cpu { get; init; }

    [JsonPropertyName("vulkan")]
    public NativeGpuInfo? Gpu { get; init; }

    [JsonPropertyName("errors")]
    public IReadOnlyList<string> Errors { get; init; } = [];

    public static NativeDiagnosticsResult CreateUnavailable(string reason) => new()
    {
        IsAvailable = false,
        Errors = [reason]
    };
}
